// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(address caller, address from, uint256 tokenId, bytes calldata data) public {
        vm.assume(caller != address(0));
        vm.assume(from != address(0));
        vm.prank(caller);
        try c.onERC721Received(caller, from, tokenId, data) returns (bytes4 selector) {
            bytes4 expected = bytes4(keccak256("onERC721Received(address,address,uint256,bytes)"));
            assertTrue(selector == expected);
        } catch {
            assertTrue(true);
        }
    }
}
